# Build the th06 (东方红魔乡) portable branch to WebAssembly via emscripten.
# Windows PowerShell version of web/build_web.sh; both must stay in sync.
#
# Prerequisites:
#   - emsdk installed and activated in this shell:  & C:\emsdk\emsdk_env.ps1
#   - src\autogenerated\Embeds.hpp present (generated by any premake run,
#     for example: premake5 vs2022)
#
# Usage:
#   $env:TH06_ASSETS_DIR = "C:\th06-assets"
#   .\web\build_web.ps1            # release (-O2)
#   .\web\build_web.ps1 -Debug     # assertions + symbols
#
# Output: dist\th06.{js,wasm} plus dist\index.html and dist\play.html.
param(
    [switch]$Debug
)

$ErrorActionPreference = "Stop"

$Proj = if ($env:TH06_PORTABLE_DIR) { $env:TH06_PORTABLE_DIR } else { Split-Path -Parent $PSScriptRoot }
$Src = Join-Path $Proj "src"
$Out = Join-Path $Proj "dist"

if (-not (Get-Command emcc -ErrorAction SilentlyContinue)) {
    Write-Error "emcc not found. Run: & C:\emsdk\emsdk_env.ps1 (or wherever emsdk is installed)"
}

if (-not (Test-Path (Join-Path $Src "autogenerated\Embeds.hpp"))) {
    Write-Error "$Src\autogenerated\Embeds.hpp missing. Run 'premake5 vs2022' in $Proj first."
}

New-Item -ItemType Directory -Force -Path $Out | Out-Null

# -Debug enables assertions + readable stack traces to diagnose aborts.
if ($Debug) {
    $OptFlags = @("-O0", "-g", "-sASSERTIONS=2", "-sSAFE_HEAP=0", "-sSTACK_OVERFLOW_CHECK=2", "-sGL_ASSERTIONS=1", "-sGL_DEBUG=1")
} else {
    $OptFlags = @("-O2")
}

# Source files mirror premake5.lua's file list. MIDI falls through to the
# MidiDefault (silent) backend since no win/linux/mac os.target matches under emscripten.
$Sources = @(
    "AnmManager.cpp",
    "AsciiManager.cpp",
    "BombData.cpp",
    "BulletData.cpp",
    "BulletManager.cpp",
    "Chain.cpp",
    "Controller.cpp",
    "EclManager.cpp",
    "EffectManager.cpp",
    "Ending.cpp",
    "EnemyEclInstr.cpp",
    "EnemyManager.cpp",
    "FileSystem.cpp",
    "GameErrorContext.cpp",
    "GameManager.cpp",
    "GameWindow.cpp",
    "Gui.cpp",
    "ItemManager.cpp",
    "main.cpp",
    "MainMenu.cpp",
    "MidiOutput.cpp",
    "MusicRoom.cpp",
    "Player.cpp",
    "PointDevice.cpp",
    "ReplayManager.cpp",
    "ResultScreen.cpp",
    "Rng.cpp",
    "ScreenEffect.cpp",
    "SoundPlayer.cpp",
    "Stage.cpp",
    "Supervisor.cpp",
    "TextHelper.cpp",
    "ZunMath.cpp",
    "utils.cpp",
    "ZunTimer.cpp",
    "graphics\GLFunc.cpp",
    "graphics\FixedFunctionGL.cpp",
    "graphics\WebGL.cpp",
    "graphics\Software.cpp",
    "pbg3\FileAbstraction.cpp",
    "pbg3\IPbg3Parser.cpp",
    "pbg3\Pbg3Archive.cpp",
    "pbg3\Pbg3Parser.cpp",
    "midi\MidiDefault.cpp",
    "thirdparty\sjis_converter.cpp"
) | ForEach-Object { Join-Path $Src $_ }

# Assets are NOT bundled into a single th06.data (that file would exceed the 20MB
# per-file limit). Instead copy each resource to dist\assets\ as an independent file
# and emit a manifest; play.html fetches them into MEMFS at startup (preRun).
if ($env:TH06_ASSETS_DIR -and (Test-Path $env:TH06_ASSETS_DIR -PathType Container)) {
    $AssetsIn = (Resolve-Path $env:TH06_ASSETS_DIR).Path
    $AssetsOut = Join-Path $Out "assets"
    Write-Host "Staging assets from $AssetsIn -> $AssetsOut (no bundling)"
    if (Test-Path $AssetsOut) { Remove-Item -Recurse -Force $AssetsOut }
    New-Item -ItemType Directory -Force -Path $AssetsOut | Out-Null
    # Copy preserving the bgm\ subdirectory structure the game expects.
    $Files = Get-ChildItem -Path $AssetsIn -Recurse -File
    $Rel = foreach ($f in $Files) {
        $r = $f.FullName.Substring($AssetsIn.TrimEnd('\').Length + 1)
        $dest = Join-Path $AssetsOut $r
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
        Copy-Item -LiteralPath $f.FullName -Destination $dest
        # The manifest uses forward slashes, like the bash script.
        $r -replace '\\', '/'
    }
    # Manifest: newline-separated relative paths, consumed by play.html. Written as
    # UTF-8 without a BOM and with \n line endings so the page parses it like the
    # bash-generated one.
    $Manifest = (($Rel | Sort-Object -CaseSensitive) -join "`n") + "`n"
    [System.IO.File]::WriteAllText((Join-Path $AssetsOut "manifest.txt"), $Manifest, (New-Object System.Text.UTF8Encoding $false))
    $Largest = $Files | Sort-Object Length -Descending | Select-Object -First 1
    Write-Host ("Staged {0} asset files." -f $Files.Count)
    Write-Host ("Largest asset: {0:N1}MB" -f ($Largest.Length / 1MB))
}

$EmccArgs = @(
    "-std=c++20",
    "-I$Src"
) + $OptFlags + @(
    "-sUSE_SDL=2",
    "-sUSE_SDL_IMAGE=2",
    # Plain comma lists instead of JSON: emcc is a .bat/.ps1 wrapper on Windows,
    # and PowerShell can strip the double quotes inside a JSON list.
    "-sSDL2_IMAGE_FORMATS=png,jpg",
    "-sUSE_SDL_TTF=2",
    "-sFULL_ES2=1",
    "-sMIN_WEBGL_VERSION=1",
    "-sMAX_WEBGL_VERSION=2",
    "-sWASM=1",
    "-sALLOW_MEMORY_GROWTH=1",
    "-sEXIT_RUNTIME=0",
    "-sFORCE_FILESYSTEM=1",
    "-sEXPORTED_RUNTIME_METHODS=FS,addRunDependency,removeRunDependency,callMain",
    "-Wno-unused-label",
    "-Wno-c99-extensions"
) + $Sources + @(
    "-o", (Join-Path $Out "th06.js")
)

# em++, not emcc: newer emscripten no longer links libc++ when the C driver links C++ objects.
Write-Host "em++ $($EmccArgs -join ' ')"
& em++ @EmccArgs
if ($LASTEXITCODE -ne 0) {
    Write-Error "em++ failed with exit code $LASTEXITCODE"
}

Write-Host ""
Write-Host "Build OK -> $Out\th06.{js,wasm}"
Write-Host "Note: emitting th06.js (NOT th06.html). The emcc-generated th06.html carries no"
Write-Host "      asset-injection logic, so opening it leaves MEMFS empty and the game aborts"
Write-Host "      on the first missing file. The hand-written index.html / play.html do the"
Write-Host "      manifest fetch into MEMFS, so always enter through those."

# play.html is the single source of truth for the page. Publish it as index.html
# (the platform's default entry) so the deployed entry always matches the source.
Copy-Item (Join-Path $Proj "web\play.html") (Join-Path $Out "index.html")
Copy-Item (Join-Path $Proj "web\play.html") (Join-Path $Out "play.html")
Write-Host "Published page -> $Out\index.html (and play.html), copied from web\play.html"

Write-Host "Serve with:  .\web\serve_web.ps1"
Write-Host "Then open:   http://localhost:8000/        (index.html)"
